import {validateEngineManifest,installEngine} from './engine-install.js';
export function engineInstaller(api){let busy=false;
 return {async open(){try{const response=await fetch('./assets/engines/manifest.json');if(!response.ok)throw Error('Engine pack unavailable.');const manifest=validateEngineManifest(await response.json()),build=manifest.builds[0],esc=api.esc;
 api.modal('Expanded FireRed',build?`<p><b>Engine preview.</b> Boot, opening, native save/reload and data-edit round trips have been tested. A full campaign and every optional battle mechanic have not.</p><p>Make a separate FireRed ROM with Shiny’s CFRU Expansion and Dynamic Pokémon Expansion. Installation runs on this device.</p><p><b>${esc(build.name)}</b> · ${esc(build.baseName)}</p><ul>${build.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p>This is a prepared engine build. Compile-time switches are fixed in this pack; source configuration still requires rebuilding. Begin a new game for this expanded save layout.</p><input id="engineBaseROM" type="file" accept=".gba"><button id="engineInstall" type="button" class="primary">Create expanded ROM</button><p id="engineInstallStatus" role="status"></p><details><summary>Engine credits and versions</summary>${build.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)}</a><br><code>${esc(s.commit)}</code></p>`).join('')}</details>`:'<p>The engine pack is being validated. No installable build is bundled in this version.</p>',null,'Back');
 if(!build)return;document.querySelector('#engineInstall').onclick=async()=>{if(busy)return;const input=document.querySelector('#engineBaseROM'),status=document.querySelector('#engineInstallStatus'),button=document.querySelector('#engineInstall'),file=input.files?.[0];if(!file){status.textContent='Choose your clean FireRed ROM first.';return;}if(file.size!==build.sourceSize){status.textContent='Choose the matching clean '+build.baseName+'.';return;}busy=true;button.disabled=true;try{status.textContent='Checking ROM and installing engine…';const response=await fetch('./'+build.patch);if(!response.ok)throw Error('Engine patch unavailable.');const bytes=await installEngine(new Uint8Array(await file.arrayBuffer()),new Uint8Array(await response.arrayBuffer()),build);await api.save(new Blob([bytes],{type:'application/octet-stream'}),'PokeBacon_Expanded_FireRed.gba');status.textContent='Expanded ROM saved. Open it in Studio to build your game.';}catch(e){status.textContent=e.message;}finally{busy=false;button.disabled=false;}};
 }catch(e){api.error(e);}}};}
